import type { ProductStyle } from './pricing.model';

// Blank product the designer draws on, managed by admins (tshirt-server models/Template.js).
// Saved products and orders keep a copy of it
export type TemplateModel = {
  id: string;
  ref: string;
  // "t-shirt" or "sweatshirt", derived from the style
  type: string;
  // Server paths (/uploads/templates/...): shown through templateImageUrl
  frontImg: string;
  // Templates without a back image can only be designed from the front
  backImg?: string;
  color: string;
  colorLabel: string;
  style?: string;
  // Generated by the server from the type, style and color: "T-shirt Oversize Black"
  label?: string;
};

// What the admin fills in: the type/style, and the color's name and swatch
export type TemplatePayload = {
  style: ProductStyle;
  colorLabel: string;
  color: string;
};
